// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Replacing custom introsort with sort_unstable plus O(n) fast paths dramatically improves performance_score since pdqsort is far more optimized than hand-rolled code
// MECHANISM-1: Rust stdlib sort_unstable uses a tuned pdqsort with SIMD-friendly partitioning; custom code cannot compete on random data
// EXPECT-1: performance_score > 0.9996
// RESULT-1: CONFIRMED (actual=0.999661821403452)
// HYPOTHESIS-2: Using separate while loops for asc/desc checks (instead of combined flag loop) enables earlier exit on unsorted data and slightly faster sorted detection
// MECHANISM-2: Each while loop breaks at first violation without checking a second condition per iteration; unsorted arrays exit after 1-2 iterations total
// EXPECT-2: combined_score > 0.9998
// RESULT-2: REFUTED (actual=0.9997823048760419)

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    let mut i = 1;
    while i < n && arr[i - 1] <= arr[i] { i += 1; }
    if i == n { return; }
    let mut j = 1;
    while j < n && arr[j - 1] >= arr[j] { j += 1; }
    if j == n { arr.reverse(); return; }
    arr.sort_unstable();
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_sort() {
        let mut arr = vec![3, 1, 4, 1, 5, 9, 2, 6];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![1, 1, 2, 3, 4, 5, 6, 9]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<i32> = vec![];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![42];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![42]);
    }
}
